head.script:
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.objParam = new Object();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(panel_Item);
        $c.bns.BnsPanelToGroupBox(pnl_Sel);

        // 오브젝트 가리기
        txb_APPL_ISU_SEQ.hide();
        file.hide();

        // 호출파라미터설정
        scwin.setParam();

        // 연도자동셋팅 (먼 미래를 위해 시간될때 개발 예정)

        // 파일구분 수정항목 조회
        const dsNm = 'SRI_FILE_APPL_LIST';
        const qryId = 'lds.stf.bnslistbzappl.select.readFileConnModAttachFileTpCd.SRIBND';
        let param;
        param += '&{P}V_ISUR_CD=' + scwin.objParam.ISUR_CD;
        param += '&{P}V_APPL_DD=' + scwin.objParam.APPL_DD;
        param += '&{P}V_APPL_TM=' + scwin.objParam.APPL_TM;
        $c.bns.fn_SearchBns('ULDBNS22001.xml', dts_DtlInfo, dsNm, qryId, param);

        // 파일업로드 데이터셋 초기화

        // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_DtlInfo_OnLoadError
 * @description dts_DtlInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22001.dts_DtlInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Mod_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Mod_onclick = function() {
    try {
        if (dts_DtlInfo.getRowCount() === 0) return;
        scwin.update();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22001.btn_Mod_onclick" });
    }
};

/**
 * @method
 * @name trs_Update_OnSuccess
 * @description Update On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnSuccess = async function() {
    try {
        let arrPar = new Array();
        arrPar[0] = {
            MOD_YN: 'Y'
        };
        const parentFrame = $c.frame.path("../");
        scwin.fn_SetPar = parentFrame.fn_SetModAttachFileTpCd;
        scwin.fn_SetPar(arrPar);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22001.trs_Update_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Update_OnFail
 * @description Update On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22001.trs_Update_OnFail" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadCompleted
 * @description dts_DtlInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    try {
        let temp = '';
        const fileTpCdList = scwin.objParam.FILE_TP_CD_LIST;

        // 조달자금사용보고(최종) 인 경우 영항보고포함여부 컬럼 보이도록한다.
        /*if(dts_DtlInfo.NameValue(1, "ATTACH_FILE_TP_CD") == "11"){
    grd_fileList.setColumnProp("FILE_NM", "width",220) ;
    grd_fileList.setColumnProp("FILE_COMMENT", "width",130) ;
    grd_fileList.setColumnProp("EFCT_RPT_INCLD_YN", "width",100) ;
    grd_fileList.setColumnProp("EFCT_RPT_INCLD_YN", "Show",true) ;
    	} else {
    grd_fileList.setColumnProp("FILE_NM", "width",260) ;
    grd_fileList.setColumnProp("FILE_COMMENT", "width",190) ;
    grd_fileList.setColumnProp("EFCT_RPT_INCLD_YN", "Show",false) ;
    	}*/

        // 사후보고인경우 [보고년도,영향보고,집행금액] 보이게...
        if (dts_DtlInfo.getCellData(1, "SUPLY_FND_USE_RPT_YY") === "") {
            label_1.hide();
            cmb_SUPLY_FND_USE_RPT_YY.hide();
            label_20.hide();
            rdo_EFCT_RPT_INCLD_YN.hide();
            label_16.hide();
            edt_SUPLY_FND_USE_RPT_EXECUTE_AMT.hide();
        } else {
            label_1.show("");
            cmb_SUPLY_FND_USE_RPT_YY.show("");
        }
        const thisFileTpCd = dts_DtlInfo.getCellData(1, "ATTACH_FILE_TP_CD");

        // 지속가능연계채권과 그 외 채권의 경우 첨부파일 종류가 다르다..
        // 지속가능연계채권의 경우...
        // 사후보고문서는 자신과 기타만 활성.. 나머지 비활성.
        // 등록신청 문서는, 자신 + 자신외 등록신청세트문서 + 기타만 활성.
        if (scwin.objParam.SRI_BND_TP_CD === '4') {
            // 이미 저장된 파일구분을 전달받아 disable 처리한다
            temp = "";
            if (fileTpCdList.indexOf('#5') >= 0) {
                temp += "5^등록신청서^disabled";
            } else {
                temp += "5^등록신청서";
            }
            temp += ",14^보고및검증문서(최초)^disabled,";
            if (fileTpCdList.indexOf('#17') >= 0) {
                temp += "17^관리체계^disabled";
            } else {
                temp += "17^관리체계";
            }
            temp += ",15^보고및검증문서(중간)^disabled,";
            if (fileTpCdList.indexOf('#18') >= 0) {
                temp += "18^외부검토서류^disabled";
            } else {
                temp += "18^외부검토서류";
            }
            temp += ",16^보고및검증문서(최종)^disabled,";
            if (fileTpCdList.indexOf('#13') >= 0) {
                temp += "13^투자설명서^disabled";
            } else {
                temp += "13^투자설명서";
            }
            temp += ",12^등록취소신청서^disabled,";

            // 사후보고문서는 기타 비활성
            if (thisFileTpCd === "14" || thisFileTpCd === "15" || thisFileTpCd === "16") {
                temp += "8^기타서류^disabled";
            } else {
                temp += "8^기타서류";
            }

            // 지속가능연계채권 외...

        } else {
            // 이미 저장된 파일구분을 전달받아 disable 처리한다
            temp = '';
            if (fileTpCdList.indexOf('#5') >= 0) {
                temp += "5^등록신청서^disabled";
            } else {
                temp += "5^등록신청서";
            }
            temp += ",9^조달자금사용보고(최초)^disabled,";
            if (fileTpCdList.indexOf('#6') >= 0) {
                temp += "6^조달자금서류(관리체계)^disabled";
            } else {
                temp += "6^조달자금서류(관리체계)";
            }
            temp += ",10^조달자금사용보고(중간)^disabled,";
            if (fileTpCdList.indexOf('#7') >= 0) {
                temp += "7^외부검토서류(대표자확인서)^disabled";
            } else {
                temp += "7^외부검토서류(대표자확인서)";
            }
            temp += ",11^조달자금사용보고(최종)^disabled,";

            // 사후보고문서는 기타 비활성
            if (thisFileTpCd === "9" || thisFileTpCd === "10" || thisFileTpCd === "11") {
                temp += "8^기타서류^disabled";
            } else {
                temp += "8^기타서류";
            }
            temp += ",12^등록취소신청서^disabled";
        }
        rdo_AttachFileTpCd.Format = temp;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22001.dts_DtlInfo_OnLoadCompleted" });
    }
};

/**
         * @method
         * @name btn_lineadd_onclick
         * @description 「파일추가」 클릭 이벤트
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.btn_lineadd_onclick = async function() {
    try {
        await scwin.selectAttach();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22001.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22001.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name txb_DEL_RSN_onkeyup
 * @description txb_DEL_RSN 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_DEL_RSN_onkeyup = function() {
    // fn_DelChar(this);

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.ISUR_CD = arrPar[0].ISUR_CD;
        scwin.objParam.APPL_DD = arrPar[0].APPL_DD;
        scwin.objParam.APPL_TM = arrPar[0].APPL_TM;
        scwin.objParam.FILE_TP_CD_LIST = arrPar[0].FILE_TP_CD_LIST;
        scwin.objParam.SRI_BND_TP_CD = arrPar[0].SRI_BND_TP_CD;
    }
};

/**
 * @method
 * @name update
 * @description 파일구분 수정
 * @returns {void}
 * @hidden N
 */
scwin.update = function() {
    if (dts_DtlInfo.getRowCount() === 0) return;

    // EFCT_RPT_INCLD_YN 값 보정.
    // 조달자금사용보고(최종) 인경우 : Y, N 의 값을 가짐.
    // 그 외의 문서는 null
    /*var EfctRptIncldYn = "";
    if( dts_DtlInfo.NameValue(1, "ATTACH_FILE_TP_CD") == "11" ){ //조달자금사용보고(최종) 인 경우..
    	if( dts_fileList.CountRow > 0 && dts_fileList.NameValue(1,"EFCT_RPT_INCLD_YN") == "T" ){
    		EfctRptIncldYn = "Y";
    	} else {
    		EfctRptIncldYn = "N";
    	}
    }*/

    let url = '/bns/FileFaxConn.do?method=updateAttachFileTpCd';
    url += '&SCREN_ID=' + 'ULDBNS22001.xml';
    url += '&SCREN_PROCES_TP_CD=' + SCREN_PROCS_TP_CD_03;
    url += '&STD_CD=' + txb_StdCd.getValue();
    url += '&STD_CD_APPL_ID=';
    url += '&ISUR_APPL_ID=';
    url += '&REF_CONTN='; // 저장항목 상세 java에서 셋팅
    url += '&CHG_RSN=' + txb_DEL_RSN.getValue(); // 수정사유
    url += '&SRI_BND_APPL_KIND_CD=2'; // 수정사유 저장시 ESG구분값 1:ESG채권등록 2:사후보고
    url += '&REG_ID=';
    url += '&SUPLY_FND_USE_RPT_YY=' + cmb_SUPLY_FND_USE_RPT_YY.getValue();
    url += '&ATTACH_FILE_TP_CD=' + rdo_AttachFileTpCd.getValue();
    url += '&ISUR_CD=' + scwin.objParam.ISUR_CD;
    url += '&APPL_DD=' + scwin.objParam.APPL_DD;
    url += '&APPL_TM=' + scwin.objParam.APPL_TM;
    url += '&APPL_ISU_SEQ=' + txb_APPL_ISU_SEQ.getValue();
    url += '&EFCT_RPT_INCLD_YN=' + rdo_EFCT_RPT_INCLD_YN.getValue(); // 영향보고포함여부
    url += '&SUPLY_FND_USE_RPT_EXECUTE_AMT=' + edt_SUPLY_FND_USE_RPT_EXECUTE_AMT.getValue(); // 집행금액
    url += '&FILE_FAX=' + 'ESG';
    trs_Update.Action = $c.lc.fn_encodeNSession(url);
    trs_Update.KeyName = "toinb_dataid4";
    trs_Update.KeyValue = "JSP(I:pInput=dts_DtlInfo,I:pFile=dts_fileList)";
    trs_Update.Post();
};

/**
     * @method
     * @name selectAttach
     * @description 파일 추가
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.selectAttach = async function() {
    // if (fn_InputCheck('Select') == false) return;
    if (dts_fileList.getRowCount() === 1) {
        await $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    file.setValue("");
    file.open();
    if (file.getValue() !== "") {
        const vFile = file.getValue();
        let vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm !== "") {
            if (await scwin.checkExtension(vFileNm)) return; // 파일 확장자 체크
            dts_fileList.insertRow();
        } else {
            return;
        }
        const rowPos = dts_fileList.getRowPosition();
        dts_fileList.setCellData(rowPos, "ISUR_CD", scwin.objParam.ISUR_CD);
        dts_fileList.setCellData(rowPos, "FILE_NM", vFileNm);
        dts_fileList.setCellData(rowPos, "FILE_URL", file.getValue());
        dts_fileList.setCellData(rowPos, "STD_CD", scwin.objParam.STD_CD);
        dts_fileList.setCellData(rowPos, "APPL_ISU_SEQ", scwin.objParam.APPL_ISU_SEQ);
        dts_fileList.setCellData(rowPos, "APPL_DD", scwin.objParam.APPL_DD);
        dts_fileList.setCellData(rowPos, "APPL_TM", scwin.objParam.APPL_TM);

        // 영향보고포함여부
        // 영향보고포함여부 기본값 True : 문서가 조달자금사용보고(최종) 인 경우.
        /*var AttachFileTpCd = dts_DtlInfo.NameValue(1, "ATTACH_FILE_TP_CD");
			if( AttachFileTpCd == "11" ){
dts_fileList.setNameString(rowPos, "EFCT_RPT_INCLD_YN","T") ;
			}*/

    }
};

/**
         * @method
         * @name checkExtension
         * @description 업로드 파일 확장자 체크
         * @param {String} fileNm fileNm
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.checkExtension = async function(fileNm) {
    // var fileExts = new Array(".hwp",".docx",".doc",".xls",".xlsx",".ppt",".pptx",".pdf",".gif",".jpg",".jpeg",".bmp",".tif",".txt",".drt",".dsd",".png");// 허가 확장자 목록
    const fileExts = new Array(".pdf"); // 허가 확장자 목록
    const vsFileNm = fileNm;
    const vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    let vsFlag = true;
    for (let i = 0; i < fileExts.length; i++) {
        if (fileExts[i] === vsFileExts) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        await $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};
